/**
 * inkvec's own palettes for the parity tests, printed by a harness that runs
 * `inkvec_trace::color::extract_palette_mdl`, `label_image` and `split_alpha_inks` (inkvec
 * 0.2.7) on the same single-precision images: the generated cases of `palette-helpers.ts` and
 * a few 128 px corpus rasters, stored here as deflated straight RGBA bytes (base64) with their
 * sources' licenses. Ink colors are inkvec's `f32` OKLab values to nine digits (they read back
 * exactly through `Math.fround`); `labelHash` is
 * `labelHash` of inkvec's labels. Generated; do not edit by hand.
 */

/** One palette inkvec recovered. */
export interface PaletteRef {
  name: string
  maxColors: number
  /** The noise the walk ran with (for a corpus raster, inkvec's `estimate_noise`). */
  sigmaNoise: number
  /** `bic_lambda` of the pixel count. */
  lambda: number
  soft: boolean
  /** Whether `split_alpha_inks` ran after labeling. */
  split: boolean
  count: number
  minted: number
  labelHash: number
  inkLab: number[]
  weight: number[]
  alpha: number[]
}

/** A corpus raster and the palettes inkvec recovered from it. */
export interface CorpusRef {
  name: string
  license: string
  w: number
  h: number
  /** Straight RGBA bytes, deflated, base64. */
  rgba: string
  refs: PaletteRef[]
}

